//! 🔖️ Ownership probes of the reserved mount and permit slots of the mounted instance.

use super::*;

impl<A: ArtifactApp, M: ReferenceSpaceMember + MemberFactory + Send + 'static> VcsArtifactApp<A, M> {
    pub(super) fn owns_original_reserved_permit(&self,cx:&StepContext<'_>)->bool{let Some(identity)=cx.original_source_parent().ok().and_then(|parent|parent.source_identity().ok()).map(|source|(cx.operation(),cx.generation(),source))else{return false};self.tools.pending_tool_lease_admission.as_ref().is_some_and(|owner|owner.identity==identity)||self.media.pending_reserved_producer_permit.as_ref().is_some_and(|(_,original)|*original==identity)}
    pub(super) fn owns_original_reserved_mount(&self,cx:&StepContext<'_>)->bool{!self.media.reserved_mount_construction.terminal_is_empty()||self.media.reserved_mount.as_ref().is_some_and(|owner|owner.matches_retirement(cx))||self.media.reserved_receipt.is_some_and(|receipt|receipt.operation(cx).is_ok())}
    pub(super) fn reserved_mount_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.media.reserved_mount_construction.terminal_is_empty(){return Ok(Default::default())}if let Some(owner)=self.media.reserved_mount.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<semio_plugin_retained_command::typed_operation::original_emission::OriginalEmissionAdmission<A>>>>(),release_bytes:size_of::<semio_plugin_retained_command::typed_operation::original_emission::OriginalEmissionAdmission<A>>(),depth:1,..Default::default()})}else{owner.close_demands(&self.tools.tool_cancellations,body)}}Ok(RetirementDemand{copy_bytes:size_of::<Option<semio_plugin_job::original_emission::OriginalEmissionReceipt>>(),depth:1,..Default::default()})}
    pub(super) fn close_original_reserved_mount(&mut self,cx:&mut StepContext<'_>)->Result<semio_framework_value::RetainedCloneStep,OriginalTurnFailure>{let before=cx.retained_progress();if !self.media.reserved_mount_construction.terminal_is_empty(){self.media.reserved_mount_construction.close_step(cx)?;return Ok(semio_framework_value::RetainedCloneStep::Progress(semio_plugin_ownership::bounded_ownership::original_lifecycle_delta(before,cx.retained_progress())?))}if let Some(owner)=self.media.reserved_mount.as_mut(){if !owner.terminal_is_empty(){cx.with_original_retirement(|cx|owner.close_step(&self.tools.tool_cancellations,cx))?;}else{let d=self.reserved_mount_close_demands(cx.retained_grant().maximum_copy_bytes)?;cx.with_original_retirement(|cx|semio_framework_job::close_original_retained_step(cx,d,|_|{if let Some(operation)=self.media.reserved_mount.take().and_then(|owner|owner.operation){self.tools.release_reserved_emit_slot(operation.operation.0)}semio_framework_value::RetainedWorkOutcome::<_,semio_framework_value::ValueError>{result:Ok(semio_framework_value::RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})),work:1}}))?;}}else if self.media.reserved_receipt.is_some(){let d=self.reserved_mount_close_demands(cx.retained_grant().maximum_copy_bytes)?;cx.with_original_retirement(|cx|semio_framework_job::close_original_retained_step(cx,d,|_|{self.media.reserved_receipt=None;semio_framework_value::RetainedWorkOutcome::<_,semio_framework_value::ValueError>{result:Ok(semio_framework_value::RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}}))?;}Ok(semio_framework_value::RetainedCloneStep::Progress(semio_plugin_ownership::bounded_ownership::original_lifecycle_delta(before,cx.retained_progress())?))}
    pub(super) fn reserved_permit_waits(&self,cx:&StepContext<'_>)->bool{let Some(identity)=cx.original_source_parent().ok().and_then(|parent|parent.source_identity().ok()).map(|source|(cx.operation(),cx.generation(),source))else{return false};self.media.pending_reserved_producer_permit.as_ref().is_some_and(|(_,original)|*original==identity)&&self.tools.pending_tool_lease_admission.as_ref().is_some_and(|owner|owner.identity!=identity)}
    pub(super) fn selected_typed_result_page(&self, receiver: u32) -> Option<(usize, u64)> {
        (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find_map(|offset| {
            let index = (self.tools.typed_result_cursor + offset) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            self.tools.tool_operations.entry(index).filter(|(_, operation)| operation.meta.instance_id == receiver && !operation.result_page_presented && operation.result_page.is_some()).map(|(id, _)| (index, *id))
        })
    }
}
